<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class StoreTransportPersonRequest extends FormRequest {public function authorize():bool{return $this->user()?->can('transporte.conductores.gestionar')??false;}public function rules():array{$company=$this->user()->company_id;$id=$this->route('person')?->id;return['person_type'=>'required|in:employee,external','employee_id'=>['nullable','required_if:person_type,employee',Rule::exists('empleados','id')->where(fn($q)=>$q->where('company_id',$company))],'name'=>'nullable|required_if:person_type,external|string|max:255','document_type'=>'nullable|string|max:20','document_number'=>['nullable','required_if:person_type,external','string','max:40',Rule::unique('transport_personnel')->where(fn($q)=>$q->where('company_id',$company))->ignore($id)],'phone'=>'nullable|string|max:40','provider'=>'nullable|string|max:255','is_driver'=>'nullable|boolean','is_monitor'=>'nullable|boolean','status'=>'required|in:active,inactive','notes'=>'nullable|string|max:2000'];}protected function prepareForValidation():void{$this->merge(['is_driver'=>$this->boolean('is_driver'),'is_monitor'=>$this->boolean('is_monitor')]);}public function withValidator($validator):void{$validator->after(function($v){if(!$this->boolean('is_driver')&&!$this->boolean('is_monitor'))$v->errors()->add('roles','Seleccione al menos un rol: conductor o monitor.');});}}
